// Normalize a date string to DD/MM/YYYY. Returns {date, ok}.
// Tries DD/MM/YYYY, DD-MM-YYYY, DD.MM.YYYY, YYYY-MM-DD. Falls back to original.
export function normalizeDate(s){
  if(!s||typeof s!=='string') return {date:'',ok:false};
  const t = s.trim();
  let m;
  // DD/MM/YYYY or DD-MM-YYYY or DD.MM.YYYY
  m = t.match(/^(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{4})$/);
  if(m){
    const d=+m[1], mo=+m[2], y=+m[3];
    if(d>=1&&d<=31&&mo>=1&&mo<=12&&y>=2020&&y<=2099){
      return {date:`${String(d).padStart(2,'0')}/${String(mo).padStart(2,'0')}/${y}`,ok:true};
    }
  }
  // YYYY-MM-DD (ISO)
  m = t.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if(m){
    const y=+m[1], mo=+m[2], d=+m[3];
    if(d>=1&&d<=31&&mo>=1&&mo<=12){
      return {date:`${String(d).padStart(2,'0')}/${String(mo).padStart(2,'0')}/${y}`,ok:true};
    }
  }
  return {date:t,ok:false};
}

// Validate invoice number format: "IN" + exactly 8 digits (Choon Hua format).
export function validInvoiceNo(s){
  if(!s||typeof s!=='string') return false;
  return /^IN\d{8}$/i.test(s.trim());
}

// Parse volume_ml and pack_size from description / product code text.
// Used as ground truth when AI's extracted volume_ml/pack_size disagree.
export function parseDesc(desc, code){
  const sources = [desc, code].filter(Boolean);
  for(const src of sources){
    const d = String(src).toUpperCase();
    let volume = null;
    const mlMatch = d.match(/(\d+(?:\.\d+)?)\s*ML/);
    // L regex: digits before L, allow letters after (product codes like "1.5LPLBTN").
    // mlMatch is tried first, so this won't accidentally swallow ML units.
    // Requires digit immediately before L (with optional space), avoiding false
    // positives on words like "BOTTLE" where there's no digit before L.
    const lMatch = d.match(/(\d+(?:\.\d+)?)\s*L/);
    if(mlMatch) volume = parseFloat(mlMatch[1]);
    else if(lMatch) volume = parseFloat(lMatch[1]) * 1000;
    let pack = null;
    const pMatch = d.match(/[X×]\s*(\d+)(?!\d)/);
    if(pMatch) pack = parseInt(pMatch[1]);
    if(volume && pack) return {volume, pack};
  }
  return {volume:null, pack:null};
}

// Downsize image base64 → smaller JPEG preview for in-app verification.
// Uses canvas. maxWidth=1024, quality=0.7 → ~100-300KB per invoice.
export function downsizeBase64ToJPEG(dataURL, maxWidth = 1024, quality = 0.7){
  return new Promise((resolve, reject) => {
    const img = new window.Image();
    img.onload = () => {
      try {
        const ratio = Math.min(maxWidth / img.width, 1);
        const canvas = document.createElement('canvas');
        canvas.width = Math.round(img.width * ratio);
        canvas.height = Math.round(img.height * ratio);
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL('image/jpeg', quality));
      } catch(e) { reject(e); }
    };
    img.onerror = () => reject(new Error('Image load failed'));
    img.src = dataURL;
  });
}

// Convert a PDF File into one File-like JPEG per page (Groq vision needs images, not PDFs).
// Renders at 2x scale for OCR-friendly sharpness, JPEG quality 0.85.
export async function pdfToImageFiles(file) {
  const arrayBuffer = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
  const baseName = file.name.replace(/\.pdf$/i, '');
  const out = [];
  for (let pageNum = 1; pageNum <= pdf.numPages; pageNum++) {
    const page = await pdf.getPage(pageNum);
    const viewport = page.getViewport({ scale: 2.0 });
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    canvas.width = viewport.width;
    canvas.height = viewport.height;
    await page.render({ canvasContext: ctx, viewport }).promise;
    const dataURL = canvas.toDataURL('image/jpeg', 0.85);
    const res = await fetch(dataURL);
    const blob = await res.blob();
    const name = pdf.numPages > 1 ? `${baseName} (p${pageNum}).jpg` : `${baseName}.jpg`;
    out.push(new File([blob], name, { type: 'image/jpeg' }));
  }
  return out;
}

// Format a volume in ml as a clean string: 1500 → "1.5L", 1000 → "1L", 320 → "320ML"
export function formatVolUnit(ml){
  if(!ml || ml <= 0) return '';
  if(ml >= 1000){
    const l = ml / 1000;
    // Use just enough decimal places to be exact: 1.0 → "1", 1.5 → "1.5", 1.75 → "1.75".
    // parseFloat strips trailing zeros so 1.50 → "1.5", 1.00 → "1".
    return `${parseFloat(l.toFixed(3))}L`;
  }
  return `${ml}ML`;
}

// Build a label from the actual item volumes inside a group, not the rate category's example list.
// Single volume → "320ML x 24". Multiple same-pack → "320ML/300ML x 24". Mixed pack → "320ML x 24 + 1.5L x 12".
// Falls back to the rate label if no item volume data is available (e.g., manually assigned category).
export function deriveActualLabel(itemVolumes, rateLabel){
  if(!itemVolumes || itemVolumes.size === 0) return rateLabel;
  const vols = Array.from(itemVolumes.values());
  if(vols.length === 1){
    return `${formatVolUnit(vols[0].volume_ml)} x ${vols[0].pack_size}`;
  }
  const samePack = vols.every(v => v.pack_size === vols[0].pack_size);
  if(samePack){
    const sortedVols = vols.map(v => v.volume_ml).sort((a,b) => b-a);
    return `${sortedVols.map(formatVolUnit).join('/')} x ${vols[0].pack_size}`;
  }
  return vols.map(v => `${formatVolUnit(v.volume_ml)} x ${v.pack_size}`).join(' + ');
}

// ============================================================
// UPDATED matchCat WITH DESCRIPTION CROSS-CHECK (PATCH 4)
// ============================================================
// Returns { cat, inconsistent, usedVol, usedPack, aiVol, aiPack, descVol, descPack }
// so the caller can know about AI extraction conflicts.
export function matchCat(volume_ml, pack_size, rates, description, code){
  const aiVolNum = Number(volume_ml);
  const aiPackNum = Number(pack_size);
  const aiVol = (volume_ml!==null && volume_ml!==undefined && !isNaN(aiVolNum) && aiVolNum>0) ? aiVolNum : null;
  const aiPack = (pack_size!==null && pack_size!==undefined && !isNaN(aiPackNum) && aiPackNum>0) ? aiPackNum : null;

  // Parse description as ground truth
  const fromDesc = parseDesc(description, code);
  const descVol = fromDesc.volume;
  const descPack = fromDesc.pack;

  // Description wins when present (text parsing more reliable than AI numeric fields)
  const usedVol = descVol || aiVol;
  const usedPack = descPack || aiPack;

  // Detect AI inconsistency (both sides must have a value to compare)
  const volMismatch = !!(descVol && aiVol && descVol !== aiVol);
  const packMismatch = !!(descPack && aiPack && descPack !== aiPack);
  const inconsistent = volMismatch || packMismatch;

  if(!usedVol || !usedPack){
    return {cat:null, inconsistent, usedVol, usedPack, aiVol, aiPack, descVol, descPack};
  }
  const cat = rates.find(r => usedVol>=r.minVol && usedVol<=r.maxVol && r.packSize===usedPack);
  return {cat: cat||null, inconsistent, usedVol, usedPack, aiVol, aiPack, descVol, descPack};
}

export function calcSub(amt,groups,p1,p2){
  const c=groups.reduce((s,g)=>s+g.ctn*g.rate,0), r=v=>Math.round(v*100)/100;
  const carton=r(c);
  // FOC / zero-amount invoices: the goods were still physically delivered, so
  // the CARTON subsidy (RM per CTN × qty) is still owed by the supplier. Only
  // the 0.4% and 0.2% percentages zero out — they're calculated on (amt - carton),
  // which would be negative when amt=0. Total = just the carton amount.
  if(!amt || amt <= 0) return {carton, p1:0, p2:0, total:carton};
  const v1=r((amt-c)*p1), v2=r((amt-c-v1)*p2);
  return {carton, p1:v1, p2:v2, total:r(c+v1+v2)};
}
