//   - Strong vision OCR + native JSON mode (responseMimeType: application/json)
//   - Browser-direct calls WORK: as of July 2026 the generativelanguage endpoint
//     returns proper CORS headers (verified — a bad key returns 400 JSON, not a
//     CORS TypeError), so NO backend proxy is needed. Just paste a key in ⚙ API.
//
// PRIVACY NOTE: Google's *free* tier may use prompts/responses to improve their
// models. These are supplier purchase invoices (amounts, product codes) — if that
// ever becomes a concern, a paid Gemini key disables training, or switch back to a
// provider that doesn't train on API data. Flip AI_PROVIDER below to change.
export const AI_PROVIDER = 'gemini';
const GROQ_MODEL = 'qwen/qwen3.6-27b';       // Groq fallback vision model (Scout decommissioned 17 Jul 2026)
const GEMINI_MODEL = 'gemini-2.5-flash';     // free tier: 1500 rpd / 250K tpm / 15 rpm, vision + JSON

// Provider-specific config used by settings UI + API call dispatch.
const PROVIDERS = {
  gemini: {
    label: 'Google Gemini',
    storageKey: 'gemini_api_key',
    placeholder: 'AIza...',
    consoleUrl: 'https://aistudio.google.com/app/apikey',
    consoleName: 'Google AI Studio',
    model: GEMINI_MODEL,
  },
  groq: {
    label: 'Groq',
    storageKey: 'groq_api_key',
    placeholder: 'gsk_...',
    consoleUrl: 'https://console.groq.com',
    consoleName: 'console.groq.com',
    model: GROQ_MODEL,
  },
};
export const AI_CFG = PROVIDERS[AI_PROVIDER];

// Delay between invoice API calls, paced to the provider's requests-per-minute cap.
// Gemini free Flash is 15 RPM. Each call itself takes a few seconds, so with a
// 3000ms gap the effective rate lands near ~10/min — comfortably under the cap
// while cutting the between-invoice wait almost in half vs the old 5s. Groq
// fallback keeps the wider 10s spacing for its tighter token-per-minute window.
export const BATCH_DELAY_MS = AI_PROVIDER === 'gemini' ? 3000 : 10000;
const B='1px solid #000';
const F='Calibri, "Segoe UI", Arial, sans-serif';

// =============================================================
// API CALL DISPATCH — provider-agnostic vision + JSON extraction
// =============================================================
// Returns { text, status } or throws Error with .code in
// { 'rate_limit', 'auth', 'malformed', 'other' } for the retry loop to handle.
export async function callAI({provider, apiKey, model, imageDataUrl, prompt}){
  if(provider === 'gemini'){
    // Gemini wants base64 separated from the data URL prefix.
    const m = /^data:(image\/[a-z+]+);base64,(.+)$/i.exec(imageDataUrl);
    if(!m) throw Object.assign(new Error('Bad image data URL'), {code:'malformed'});
    const [, mimeType, base64Data] = m;

    const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${encodeURIComponent(apiKey)}`;
    const res = await fetch(url, {
      method:'POST',
      headers:{'Content-Type':'application/json'},
      body: JSON.stringify({
        contents:[{
          parts:[
            {text: prompt},
            {inline_data: {mime_type: mimeType, data: base64Data}},
          ],
        }],
        generationConfig:{
          temperature: 0.1,
          maxOutputTokens: 6000,  // long invoices have 20+ line items; 2000 caused JSON truncation
          responseMimeType: 'application/json',
          // Disable Gemini 2.5's default "thinking" pass. It's pure latency for a
          // structured-extraction task (we're reading, not reasoning), and on 2.5
          // it also burns the output-token budget. Setting the budget to 0 makes
          // Flash respond ~2-3x faster with no accuracy loss for OCR.
          thinkingConfig:{ thinkingBudget: 0 },
        },
      }),
    });
    if(res.status === 429){
      throw Object.assign(new Error('Rate limit — retrying...'), {code:'rate_limit'});
    }
    if(res.status === 401 || res.status === 403){
      throw Object.assign(new Error('API key rejected — check your Gemini key in settings'), {code:'auth'});
    }
    const data = await res.json();
    if(data.error){
      const msg = data.error.message || JSON.stringify(data.error);
      if(/quota|rate/i.test(msg)) throw Object.assign(new Error('Rate limit — retrying...'), {code:'rate_limit'});
      throw Object.assign(new Error(msg), {code:'other'});
    }
    const text = data.candidates?.[0]?.content?.parts?.[0]?.text || '';
    if(!text) throw Object.assign(new Error('Gemini returned empty response'), {code:'malformed'});
    return {text};
  }

  // Groq fallback (OpenAI-compatible API)
  const res = await fetch('https://api.groq.com/openai/v1/chat/completions', {
    method:'POST',
    headers:{'Content-Type':'application/json', 'Authorization':`Bearer ${apiKey}`},
    body: JSON.stringify({
      model,
      messages:[{role:'user', content:[
        {type:'image_url', image_url:{url: imageDataUrl}},
        {type:'text', text: prompt},
      ]}],
      max_tokens:4000, temperature:0.1,  // shrunk image leaves room for response; 4000 fits 25+ line items
    }),
  });
  const data = await res.json();
  if(data.error){
    const msg = data.error.message || JSON.stringify(data.error);
    if(msg.includes('Rate limit') || res.status === 429){
      throw Object.assign(new Error('Rate limit — retrying...'), {code:'rate_limit'});
    }
    if(res.status === 401 || res.status === 403){
      throw Object.assign(new Error('API key rejected — check your Groq key in settings'), {code:'auth'});
    }
    throw Object.assign(new Error(msg), {code:'other'});
  }
  const text = (data.choices?.[0]?.message?.content || '').trim();
  return {text};
}

