// Click-to-edit Amount component — always displays formatted RM value, switches to input when clicked
export function EditableAmount({value,onCommit,format,align='center'}){
  const [editing,setEditing]=useState(false);
  const [local,setLocal]=useState(String(value));
  const ref=useRef(null);
  useEffect(()=>{ if(!editing) setLocal(String(value)); },[value,editing]);
  useEffect(()=>{ if(editing&&ref.current){ ref.current.focus(); ref.current.select(); } },[editing]);
  const commit=()=>{
    const n=parseFloat(local);
    if(!isNaN(n)&&n>=0&&n!==value) onCommit(n);
    setEditing(false);
  };
  if(editing){
    return <input ref={ref} type="number" step="0.01" value={local}
      onChange={e=>setLocal(e.target.value)}
      onBlur={commit}
      onKeyDown={e=>{ if(e.key==='Enter'){e.preventDefault();commit();} if(e.key==='Escape'){setLocal(String(value));setEditing(false);} }}
      className="noP"
      style={{width:'100%',border:'1px solid #2563eb',borderRadius:3,padding:'3px 4px',fontSize:16,fontFamily:F,textAlign:align,fontWeight:700,boxSizing:'border-box',background:'#fff'}}/>;
  }
  return <span
    onClick={()=>setEditing(true)}
    className="editable-text"
    title="Click to edit amount"
    style={{display:'block',cursor:'text',padding:'3px 4px',borderRadius:3,fontSize:16,fontWeight:700,textAlign:align,fontVariantNumeric:'tabular-nums'}}
  >{format(value)}</span>;
}

// Click-to-edit CTN component — always shows plain number, switches to input when clicked
function EditableCtn({value,onCommit}){
  const [editing,setEditing]=useState(false);
  const [local,setLocal]=useState(String(value));
  const ref=useRef(null);
  useEffect(()=>{ if(!editing) setLocal(String(value)); },[value,editing]);
  useEffect(()=>{ if(editing&&ref.current){ ref.current.focus(); ref.current.select(); } },[editing]);
  const commit=()=>{
    const n=parseInt(local);
    if(!isNaN(n)&&n>=0&&n!==value) onCommit(n);
    setEditing(false);
  };
  if(editing){
    return <input ref={ref} type="number" min="0" value={local}
      onChange={e=>setLocal(e.target.value)}
      onBlur={commit}
      onKeyDown={e=>{ if(e.key==='Enter'){e.preventDefault();commit();} if(e.key==='Escape'){setLocal(String(value));setEditing(false);} }}
      className="noP"
      style={{width:50,border:'1px solid #2563eb',borderRadius:3,padding:'1px 4px',fontSize:15,fontFamily:F,textAlign:'right',fontWeight:600,verticalAlign:'baseline'}}/>;
  }
  return <span
    onClick={()=>setEditing(true)}
    className="editable-text"
    title="Click to edit CTN count"
    style={{cursor:'text',fontWeight:600,padding:'1px 4px',borderRadius:3}}
  >{value}</span>;
}

// Click-to-edit Text component (PATCH 3) — generic text field for invoice_no, invoice_date
export function EditableText({value,onCommit,placeholder='—',invalid=false}){
  const [editing,setEditing]=useState(false);
  const [local,setLocal]=useState(String(value||''));
  const ref=useRef(null);
  useEffect(()=>{ if(!editing) setLocal(String(value||'')); },[value,editing]);
  useEffect(()=>{ if(editing&&ref.current){ ref.current.focus(); ref.current.select(); } },[editing]);
  const commit=()=>{
    const v=local.trim();
    if(v !== String(value||'')) onCommit(v);
    setEditing(false);
  };
  if(editing){
    return <input ref={ref} type="text" value={local}
      onChange={e=>setLocal(e.target.value)}
      onBlur={commit}
      onKeyDown={e=>{ if(e.key==='Enter'){e.preventDefault();commit();} if(e.key==='Escape'){setLocal(String(value||''));setEditing(false);} }}
      className="noP"
      style={{width:'100%',border:'1px solid #2563eb',borderRadius:3,padding:'2px 4px',fontSize:15,fontFamily:F,textAlign:'center',boxSizing:'border-box',background:'#fff'}}/>;
  }
  return <span
    onClick={()=>setEditing(true)}
    className="editable-text"
    title="Click to edit"
    style={{
      display:'inline-block',
      cursor:'text',
      padding:'2px 4px',
      borderRadius:3,
    }}
  >{value || placeholder}</span>;
}

// Inline editor for the side-by-side comparison modal — always-visible input field
// so fields look obviously editable. Commits on blur or Enter. Esc cancels.
function ModalInput({value, onCommit, placeholder, type='text', step, mono=false, bold=false, narrow=false}){
  const [local, setLocal] = useState(String(value ?? ''));
  useEffect(()=>{ setLocal(String(value ?? '')); }, [value]);
  const commit = () => {
    if(local !== String(value ?? '')) onCommit(local);
  };
  return (
    <input
      type={type}
      step={step}
      value={local}
      placeholder={placeholder}
      onChange={e=>setLocal(e.target.value)}
      onBlur={commit}
      onKeyDown={e=>{
        if(e.key==='Enter'){e.preventDefault(); e.target.blur();}
        if(e.key==='Escape'){e.stopPropagation(); setLocal(String(value ?? '')); e.target.blur();}
      }}
      style={{
        width: narrow ? 64 : '100%',
        padding: bold ? '7px 10px' : '6px 10px',
        border: '1px solid #d1d5db',
        borderRadius: 4,
        background: '#fff',
        fontSize: bold ? 16 : 13,
        fontWeight: bold ? 700 : 'normal',
        fontFamily: mono ? 'monospace' : F,
        boxSizing: 'border-box',
        textAlign: narrow ? 'right' : 'left',
        color: '#111',
      }}
    />
  );
}

// ============================================================
// MAIN COMPONENT
// ============================================================

export default function InvoiceExtractor() {
  const [invoices,setInvoices]=useState([]);
  const [uploading,setUploading]=useState(false);
  const [processing,setProcessing]=useState(false);
  const [processingCount,setProcessingCount]=useState({done:0,total:0});
  const [error,setError]=useState(null);
  const [drag,setDrag]=useState(false);
  const [cnValues,setCnValues]=useState({});
  const [apiKey,setApiKey]=useState('');
  const [keyInput,setKeyInput]=useState('');
  const [showSettings,setShowSettings]=useState(false);
  const [manualEntry,setManualEntry]=useState({});  // { invId: { rateId, ctn } }
  const [previewInvId,setPreviewInvId]=useState(null);  // invoice id whose source we're viewing
  const fileRef=useRef(null);
  const uploadAreaRef=useRef(null);

  // When user clicks "+ Add Invoice", scroll the upload dropzone into view.
  // Without this, the dropzone renders below the existing invoice table — off-screen
  // since the user already scrolled down to click the button. Looks like nothing happened.
  useEffect(()=>{
    if(uploading && invoices.length>0 && uploadAreaRef.current){
      // Defer to next tick so DOM has rendered the dropzone
      setTimeout(()=>{
        uploadAreaRef.current?.scrollIntoView({behavior:'smooth', block:'center'});
      }, 50);
    }
  },[uploading, invoices.length]);
  const config=SUPPLIERS['CHOON HUA'];

  // The live invoice being previewed (lookup ensures it stays in sync with edits)
  const previewInv = previewInvId ? invoices.find(i => i.id === previewInvId) : null;

  // Esc closes preview modal (unless user is typing in an input)
  useEffect(() => {
    if (!previewInvId) return;
    const handler = e => {
      if (e.key === 'Escape') {
        if (document.activeElement?.tagName === 'INPUT') return;
        setPreviewInvId(null);
      }
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [previewInvId]);

  useEffect(()=>{
    try{ const k=localStorage.getItem(AI_CFG.storageKey); if(k) setApiKey(k); }catch(e){}
  },[]);

  const saveKey=()=>{
    if(!keyInput.trim())return;
    setApiKey(keyInput.trim());
    try{localStorage.setItem(AI_CFG.storageKey,keyInput.trim());}catch(e){}
    setShowSettings(false);
  };

  const setCn=(id,val)=>setCnValues(prev=>({...prev,[id]:parseFloat(val)||0}));

  // Manually edit the CTN count for a specific category group within an invoice
  const updateGroupCtn=(invId,rateId,newCtn)=>{
    const ctn=parseInt(newCtn);
    if(isNaN(ctn)||ctn<0) return;
    setInvoices(prev=>{
      const updated = prev.map(inv=>{
        if(inv.id!==invId) return inv;
        const groups=inv.groups.map(g=>g.id===rateId?{...g,ctn}:g);
        const sub=calcSub(inv.raw.total_amount,groups,config.pct1,config.pct2);
        return {...inv,groups,subsidy:sub, _issuesDismissed:false};
      });
      return updated.map(inv => ({...inv, issues: recomputeIssues(inv, updated)}));
    });
  };

  // Manually edit total_amount on an invoice
  const updateInvoiceAmount=(invId,newAmount)=>{
    const amt=parseFloat(newAmount);
    if(isNaN(amt)||amt<0) return;
    setInvoices(prev=>{
      const updated = prev.map(inv=>{
        if(inv.id!==invId) return inv;
        const sub=calcSub(amt,inv.groups,config.pct1,config.pct2);
        return {...inv,raw:{...inv.raw,total_amount:amt},subsidy:sub, _issuesDismissed:false};
      });
      return updated.map(inv => ({...inv, issues: recomputeIssues(inv, updated)}));
    });
  };

  // PATCH 7 — Update invoice_no / invoice_date / supplier, with auto-normalize + dup recheck
  const updateInvoiceField=(invId, field, value)=>{
    setInvoices(prev=>{
      const updated = prev.map(inv=>{
        if(inv.id!==invId) return inv;
        let normalized = value;
        if(field==='invoice_date'){
          const dc = normalizeDate(value);
          if(dc.ok) normalized = dc.date;
        }
        // Numeric fields used in calcSub must be numbers, not strings
        if(field==='total_amount'){
          const n = parseFloat(value);
          normalized = isNaN(n) ? 0 : n;
        }
        const updatedInv = {...inv, raw:{...inv.raw, [field]: normalized}, _issuesDismissed:false};
        // If total_amount changed, recompute subsidy — 0.4% and 0.2% depend on it.
        if(field==='total_amount'){
          updatedInv.subsidy = calcSub(updatedInv.raw.total_amount, updatedInv.groups, config.pct1, config.pct2);
        }
        return updatedInv;
      });
      // Recompute all issues because invoice_no change affects duplicate status across all invoices
      return updated.map(inv => ({...inv, issues: recomputeIssues(inv, updated)}));
    });
  };

  // PATCH 7 — Dismiss issues banner (user has reviewed them)
  const dismissIssues=(invId)=>{
    setInvoices(prev => prev.map(inv =>
      inv.id===invId ? {...inv, _issuesDismissed:true} : inv
    ));
  };

  // Remove a single invoice from the batch (useful for duplicates)
  const removeInvoice=(invId)=>{
    setInvoices(prev=>{
      const updated = prev.filter(inv => inv.id !== invId);
      // Recompute issues for survivors since removing a dup may clear DUPLICATE flag on others
      return updated.map(inv => ({...inv, issues: recomputeIssues(inv, updated)}));
    });
    setCnValues(prev => {
      const next = {...prev};
      delete next[invId];
      return next;
    });
  };

  // Manually assign a category (works for both empty-groups invoices and adding more to existing).
  // If the rate is already in the invoice's groups, sums the CTN. Otherwise appends a new group.
  const assignCategory=(invId,rateId,ctnInput)=>{
    const rate=config.rates.find(r=>r.id===rateId);
    const ctn=parseInt(ctnInput);
    if(!rate||!ctn||ctn<=0) return;
    setInvoices(prev=>{
      const updated = prev.map(inv=>{
        if(inv.id!==invId) return inv;
        const existing = inv.groups.find(g=>g.id===rateId);
        let groups;
        if(existing){
          groups = inv.groups.map(g => g.id===rateId ? {...g, ctn: g.ctn + ctn} : g);
        } else {
          groups = [...inv.groups, {...rate, ctn}];
        }
        const sub=calcSub(inv.raw.total_amount,groups,config.pct1,config.pct2);
        return {...inv, groups, subsidy:sub, _manuallyAssigned:true, _issuesDismissed:false};
      });
      return updated.map(inv => ({...inv, issues: recomputeIssues(inv, updated)}));
    });
    // Clear the manual-entry input after applying
    setManualEntry(p=>({...p, [invId]: {rateId:'', ctn:''}}));
  };

  // Update the PRODUCT TOTAL declared value (from invoice header) — affects mismatch checks.
  const updateDeclaredTotal=(invId, value)=>{
    const total = parseInt(value);
    if(isNaN(total) || total < 0) return;
    setInvoices(prev=>{
      const updated = prev.map(inv=>{
        if(inv.id!==invId) return inv;
        return {...inv, declaredTotal: total, _issuesDismissed:false};
      });
      return updated.map(inv => ({...inv, issues: recomputeIssues(inv, updated)}));
    });
  };

  // Manually adjust a subsidy line (carton, p1, or p2). Total auto-recomputes as sum.
  // Edits to CTN / amount / categories will overwrite these via calcSub.
  const updateSubsidyLine=(invId, line, value)=>{
    const v = parseFloat(value);
    if(isNaN(v) || v < 0) return;
    if(!['carton','p1','p2'].includes(line)) return;
    setInvoices(prev=>{
      const updated = prev.map(inv=>{
        if(inv.id!==invId) return inv;
        const r = n => Math.round(n*100)/100;
        const newSub = {...inv.subsidy, [line]: r(v)};
        newSub.total = r((newSub.carton||0) + (newSub.p1||0) + (newSub.p2||0));
        return {...inv, subsidy: newSub, _issuesDismissed:false};
      });
      return updated.map(inv => ({...inv, issues: recomputeIssues(inv, updated)}));
    });
  };

  // Remove a category from an invoice's groups (user clicks × in the modal).
  // Recomputes subsidy and issues after removal.
  const removeGroup=(invId, rateId)=>{
    setInvoices(prev=>{
      const updated = prev.map(inv=>{
        if(inv.id!==invId) return inv;
        const groups = inv.groups.filter(g => g.id !== rateId);
        const sub = calcSub(inv.raw.total_amount, groups, config.pct1, config.pct2);
        return {...inv, groups, subsidy:sub, _issuesDismissed:false};
      });
      return updated.map(inv => ({...inv, issues: recomputeIssues(inv, updated)}));
    });
  };

  const processSingleFile=useCallback(async (file)=>{
    if(!file?.type.startsWith('image/')) throw new Error('Not an image file: '+file.name);
    return new Promise((resolve,reject)=>{
      const reader=new FileReader();
      reader.onload=async()=>{
        try{
          let lastErr=null;
          // Downsize the image once before any API attempt. Full-resolution PDF renders
          // are ~7K tokens each — too big for Qwen 3.6's 8K TPM free tier ceiling.
          // 1280px @ JPEG 0.75 lands at ~1.5-2K tokens with no real OCR quality loss
          // for printed invoices. This is the single biggest token saver.
          let optimizedImage;
          try {
            optimizedImage = await downsizeBase64ToJPEG(reader.result, 1280, 0.75);
          } catch(e) {
            console.warn('Image downsize failed, using original:', e);
            optimizedImage = reader.result;
          }
          // Rate-limit backoff schedule. The provider's per-minute window is 60s,
          // so we space retries to actually cross window boundaries instead of all
          // hammering inside the same locked window.
          // Schedule (cumulative): 0s, 15s, 35s, 65s, 95s — total ~95s worst case.
          const BACKOFF_MS = [0, 15000, 20000, 30000, 30000];
          for(let attempt=0; attempt<BACKOFF_MS.length; attempt++){
            try{
              if(BACKOFF_MS[attempt]>0) await new Promise(r=>setTimeout(r,BACKOFF_MS[attempt]));
              let txt;
              try {
                const result = await callAI({
                  provider: AI_PROVIDER,
                  apiKey,
                  model: AI_CFG.model,
                  imageDataUrl: optimizedImage,
                  prompt: PROMPT,
                });
                txt = (result.text||'').trim().replace(/```json|```/g,'').trim();
              } catch(apiErr) {
                if(apiErr.code === 'rate_limit'){
                  // Final attempt — surface a helpful message, not "retrying..."
                  if(attempt === BACKOFF_MS.length - 1){
                    lastErr = new Error('Rate limit hit even after retries. Wait a minute, or add a credit card to Groq (console.groq.com/settings/billing) for 10x higher limits — costs $0 if you stay under free quota.');
                  } else {
                    lastErr = apiErr;
                  }
                  continue;
                }
                throw apiErr;  // auth/malformed/other surface immediately
              }
              // Strip any prose before/after the JSON object
              if(!txt.startsWith('{')) txt=txt.substring(txt.indexOf('{'));
              if(!txt.endsWith('}')) txt=txt.substring(0,txt.lastIndexOf('}')+1);
              // Remove trailing commas (common AI output flaw)
              txt=txt.replace(/,\s*}/g,'}').replace(/,\s*]/g,']');

              // Try strict parse first; fall back to aggressive repair for unquoted keys
              let parsed;
              try {
                parsed = JSON.parse(txt);
              } catch (parseErr) {
                // AI sometimes returns unquoted property names like `total_amount: 7800.80`
                // Add quotes to any bare key immediately after `{` or `,`
                const repaired = txt.replace(/([{,]\s*)([a-zA-Z_][a-zA-Z0-9_]*)\s*:/g, '$1"$2":');
                try {
                  parsed = JSON.parse(repaired);
                  console.warn(`[Invoice] ${file.name}: JSON auto-repaired (unquoted keys)`);
                } catch (repairErr) {
                  // Both failed — surface a user-friendly error, not the raw parser output
                  console.error('[Invoice] Raw AI response:', txt);
                  const isTruncated = /Unexpected end/i.test(parseErr.message);
                  const hint = isTruncated
                    ? 'Response was cut off mid-data (invoice may have too many line items). Try splitting the invoice or contact dev.'
                    : 'Try re-uploading, or use a clearer/sharper photo.';
                  throw new Error(`AI returned malformed data for "${file.name}". ${hint} (Technical: ${parseErr.message})`);
                }
              }

              // PATCH 6 — normalize date at source
              const dc = normalizeDate(parsed.invoice_date);
              if(dc.ok) parsed.invoice_date = dc.date;

              // PATCH 6 — match every item with cross-check metadata
              const items=(parsed.items||[]).map(it=>{
                const m=matchCat(it.volume_ml, it.pack_size, config.rates, it.description, it.product_code);
                return {
                  ...it,
                  category: m.cat,
                  _inconsistent: m.inconsistent,
                  _aiVol: m.aiVol,
                  _aiPack: m.aiPack,
                  _descVol: m.descVol,
                  _descPack: m.descPack,
                  _usedVol: m.usedVol,
                  _usedPack: m.usedPack,
                };
              });

              const unmatched=items.filter(it=>!it.category);
              if(unmatched.length>0){
                console.warn('[Invoice]',parsed.invoice_no,'has',unmatched.length,'unmatched items:',
                  unmatched.map(u=>({desc:u.description,code:u.product_code,vol:u._usedVol,pack:u._usedPack})));
              }

              // SANITY CHECK: extracted items qty sum should equal PRODUCT TOTAL on invoice
              const itemsQtySum = items.reduce((s,it)=>s+(Number(it.qty)||0),0);
              const declaredTotal = Number(parsed.total_qty)||0;
              if(declaredTotal>0 && Math.abs(itemsQtySum-declaredTotal)>0){
                console.warn('[Invoice]',parsed.invoice_no,
                  `CARTON MISMATCH: items sum to ${itemsQtySum} but PRODUCT TOTAL on invoice is ${declaredTotal}. AI likely missed line items.`);
              }

              const gMap={};
              items.forEach(it=>{
                if(!it.category) return;
                const k=it.category.id;
                if(!gMap[k]){
                  gMap[k] = {...it.category, ctn:0, _itemVolumes: new Map()};
                }
                gMap[k].ctn += Number(it.qty) || 0;
                // Track actual volume from this item for correct label derivation later
                const vol = it._usedVol || it.volume_ml;
                const pack = it._usedPack || it.pack_size;
                if(vol && pack){
                  const volKey = `${vol}|${pack}`;
                  if(!gMap[k]._itemVolumes.has(volKey)){
                    gMap[k]._itemVolumes.set(volKey, {volume_ml:vol, pack_size:pack, ctn:0});
                  }
                  gMap[k]._itemVolumes.get(volKey).ctn += Number(it.qty) || 0;
                }
              });

              // Derive each group's label from ACTUAL item volumes (not rate category list)
              Object.values(gMap).forEach(g => {
                g.label = deriveActualLabel(g._itemVolumes, g.label);
                delete g._itemVolumes;  // strip the Map before storing (won't serialize)
              });

              const groupKeys=Object.keys(gMap);

              // AUTO-CORRECT: single-category invoice trusts PRODUCT TOTAL over extracted line items
              const extractedCtnSumPreCorrect = Object.values(gMap).reduce((s,g)=>s+g.ctn,0);
              if(groupKeys.length===1 && declaredTotal>0 && declaredTotal!==gMap[groupKeys[0]].ctn){
                console.info('[Invoice]',parsed.invoice_no,'auto-correcting CTN',gMap[groupKeys[0]].ctn,'→',declaredTotal,'based on PRODUCT TOTAL');
                gMap[groupKeys[0]].ctn=declaredTotal;
              }
              const groups=Object.values(gMap);
              const extractedCtnSum=groups.reduce((s,g)=>s+g.ctn,0);

              const sub=calcSub(parsed.total_amount,groups,config.pct1,config.pct2);
              const id='inv_'+Date.now()+'_'+Math.random().toString(36).slice(2,6);

              // PATCH 5/6 — compute initial issues (without dup check yet — that's done in processFiles)
              const issues = computeIssues({
                parsed,
                items,
                groups,
                declaredTotal,
                duplicateInfo: null,  // set in processFiles against full batch via recomputeIssues
                extractedCtnSum,
                manuallyAssigned: false,
              });

              // Generate downsized preview for in-app verification (non-blocking — failure is OK)
              let imagePreview = null;
              try { imagePreview = await downsizeBase64ToJPEG(reader.result, 1024, 0.7); }
              catch(e) { console.warn('Image preview generation failed for', file.name, e); }

              resolve({raw:parsed,items,groups,subsidy:sub,id,issues,declaredTotal, image: imagePreview, _issuesDismissed:false, _manuallyAssigned:false});
              return;
            }catch(inner){lastErr=inner;}
          }
          reject(lastErr||new Error('Failed after retries'));
        }catch(e){reject(e);}
      };
      reader.onerror=()=>reject(new Error('Failed to read file'));
      reader.readAsDataURL(file);
    });
  },[config,apiKey]);

  const processFiles=useCallback(async (files)=>{
    if(!apiKey){setError(`Set your ${AI_CFG.label} API key first`);setShowSettings(true);return;}
    const fileArr=Array.from(files);
    if(fileArr.length===0){setError('No files selected');return;}

    setError(null);setProcessing(true);

    // Expand PDFs into individual JPEG files (Groq vision needs images, not PDFs).
    // PDFs and images get mixed into one queue, preserving upload order.
    const imageFiles=[];
    for(const f of fileArr){
      const isPdf = f.type==='application/pdf' || /\.pdf$/i.test(f.name);
      if(isPdf){
        try{
          const pages = await pdfToImageFiles(f);
          imageFiles.push(...pages);
        }catch(e){
          console.error('PDF conversion failed for',f.name,e);
          setError(prev=>(prev?prev+'\n':'')+`Failed to read PDF: ${f.name} — ${e.message}`);
        }
      }else if(f.type.startsWith('image/')){
        imageFiles.push(f);
      }
    }
    if(imageFiles.length===0){
      setError('No valid image or PDF files selected');
      setProcessing(false);
      return;
    }

    setProcessingCount({done:0,total:imageFiles.length});
    const results=[];
    for(let i=0;i<imageFiles.length;i++){
      try{
        if(i>0) await new Promise(r=>setTimeout(r,BATCH_DELAY_MS));
        const inv=await processSingleFile(imageFiles[i]);
        results.push(inv);
        setProcessingCount(prev=>({...prev,done:prev.done+1}));
      }catch(e){
        console.error('Error processing',imageFiles[i].name,e);
        setError(prev=>(prev?prev+'\n':'')+`Failed: ${imageFiles[i].name} — ${e.message}`);
      }
    }
    if(results.length>0){
      // PATCH 6b — merge new results, then recompute issues for everything (catches dups within batch + against existing)
      setInvoices(prev => {
        const merged = [...prev, ...results];
        return merged.map(inv => ({...inv, issues: recomputeIssues(inv, merged)}));
      });
      setCnValues(prev=>{const next={...prev};results.forEach(r=>{if(next[r.id]==null)next[r.id]=0;});return next;});
    }
    setUploading(false);setProcessing(false);
    if(fileRef.current) fileRef.current.value='';
  },[processSingleFile,apiKey]);

  const gT=invoices.reduce((s,i)=>s+i.raw.total_amount,0);
  const gC=invoices.reduce((s,i)=>s+i.subsidy.carton,0);
  const gP1=invoices.reduce((s,i)=>s+i.subsidy.p1,0);
  const gP2=invoices.reduce((s,i)=>s+i.subsidy.p2,0);
  const gS=Math.round((gC+gP1+gP2)*100)/100;
  const totalCn=Object.values(cnValues).reduce((s,v)=>s+v,0);
  const tA=Math.round((gT-gS)*100)/100;
  const tP=Math.round((tA-totalCn)*100)/100;

  // Total open issues (errors only, for the warning badge at the top)
  const openErrorCount = invoices.reduce((s,i)=>
    s + ((i.issues && !i._issuesDismissed) ? i.issues.filter(x=>x.severity==='error').length : 0)
  , 0);
  const openWarnCount = invoices.reduce((s,i)=>
    s + ((i.issues && !i._issuesDismissed) ? i.issues.filter(x=>x.severity==='warn').length : 0)
  , 0);

  const downloadExcel=()=>{
    const wb=XLSX.utils.book_new(),d=[];
    d.push([CO.name+' '+CO.reg]);d.push([CO.addr]);d.push(['Tel: '+CO.tel+'    E-mail: '+CO.email]);
    d.push([]);d.push(['PAYMENT SUMMARY']);d.push(['SUPPLIER: '+config.name]);d.push([]);
    d.push(['NO.','DATE','INVOICE NO.','AMOUNT','CN','','TRANSPORT SUBSIDY','']);
    invoices.forEach((inv,idx)=>{const cn=cnValues[inv.id]||0;inv.groups.forEach((g,gi)=>{
      d.push([gi===0?idx+1:'',gi===0?inv.raw.invoice_date:'',gi===0?inv.raw.invoice_no:'',gi===0?inv.raw.total_amount:'',gi===0&&cn?-cn:'','',g.label,'']);
      d.push(['','','','','','',g.ctn+' CTN x RM'+g.rate.toFixed(2)+' =',g.ctn*g.rate]);
      d.push(['','','','','','','+ 0.4% =',inv.subsidy.p1]);
      d.push(['','','','','','','+ 0.2% =',inv.subsidy.p2]);
    });});
    // Column footer: invoice total under AMOUNT (col D, index 3), CN sum under CN (col E, index 4).
    d.push(['','','TOTAL:',gT,totalCn?-totalCn:0,'','','']);
    d.push([]);
    d.push(['','','','','','','CARTON:',gC]);
    d.push(['','','','','','','0.4%:',gP1]);
    d.push(['','','','','','','0.2%:',gP2]);
    d.push(['','','','','','','TOTAL SUBSIDY:',gS]);
    d.push([]);
    d.push(['','','','','TOTAL AMOUNT PAYABLE = RM'+tP.toFixed(2)]);
    const ws=XLSX.utils.aoa_to_sheet(d);
    ws['!cols']=[{wch:5},{wch:12},{wch:16},{wch:16},{wch:10},{wch:2},{wch:24},{wch:14}];
    XLSX.utils.book_append_sheet(wb,ws,'Payment Summary');
    XLSX.writeFile(wb,'Payment_Summary_'+config.name.split(' ')[0]+'.xlsx');
  };

  const reset=()=>{setInvoices([]);setUploading(false);setProcessing(false);setError(null);setCnValues({});setManualEntry({});setPreviewInvId(null);if(fileRef.current)fileRef.current.value='';};
  const showUpload=invoices.length===0||uploading;

  return(
    <div style={{fontFamily:F,fontSize:16,background:'#fff',color:'#000',minHeight:'100vh'}}>
      <style>{`
        @keyframes spin{to{transform:rotate(360deg)}}
        .editable-text:hover{background:#f0f9ff;outline:1px dashed #93c5fd;outline-offset:-1px}
        .printOnly{display:none}
        @media print{
          .noP{display:none!important}
          .screenOnly{display:none!important;visibility:hidden!important;width:0!important;height:0!important;overflow:hidden!important;position:absolute!important}
          .printOnly{display:inline!important;visibility:visible!important}
          body,html{margin:0;padding:0;background:#fff}
          @page{size:A4 portrait;margin:8mm 8mm}
          .wrap{max-width:100%!important;padding:0!important}
          .print-area{font-size:12px!important}
          .print-area h1,.print-area h2,.print-area h3{font-size:14px!important;margin:4px 0!important}
          .print-area table{font-size:11px!important}
          .print-area td,.print-area th{padding:4px 6px!important}
          .print-area .total-payable{font-size:18px!important;margin-top:10px!important}
          .print-area img{max-height:80px!important}
          .print-area,.print-area table{page-break-inside:avoid}
          .print-area tr{page-break-inside:avoid}
        }
      `}</style>

      <div className="wrap print-area" style={{maxWidth:780,margin:'0 auto',padding:'20px'}}>

        {/* HEADER — compact letterhead layout.
            Logo absolute on the left (doesn't push text off-center).
            Text stacked tightly: 4 lines, all one-liners, neat spacing. */}
        <div style={{
          position:'relative',
          textAlign:'center',
          paddingBottom:8,
          borderBottom:'2px solid #000',
          minHeight:90,
        }}>
          {/* Logo — sized to match text block height (~85px) so they align as a single row, no wasted vertical space */}
          <img src={LOGO} alt="CJK" style={{
            position:'absolute',
            left:0,
            top:'50%',
            transform:'translateY(-50%)',
            height:85,
            maxWidth:95,
            objectFit:'contain',
          }}/>

          {/* Text block — tight padding around logo, all single-line */}
          <div style={{padding:'2px 105px 0',lineHeight:1.3}}>
            <div style={{fontSize:18,fontWeight:700,letterSpacing:0.3,whiteSpace:'nowrap'}}>{CO.name}</div>
            <div style={{fontSize:12,marginTop:0,opacity:0.75,whiteSpace:'nowrap'}}>{CO.reg}</div>
            <div style={{fontSize:12,marginTop:5,whiteSpace:'nowrap'}}>{CO.addr}</div>
            <div style={{fontSize:12,marginTop:1,whiteSpace:'nowrap'}}>
              Tel: {CO.tel} &nbsp;&nbsp;&nbsp; E-mail: <a href={'mailto:'+CO.email} style={{color:'#0056b3'}}>{CO.email}</a>
            </div>
          </div>

          {/* API button — absolute right, screen only */}
          <button className="noP" onClick={()=>setShowSettings(!showSettings)}
            style={{
              position:'absolute',
              right:0,
              top:'50%',
              transform:'translateY(-50%)',
              background:'none',
              border:'1px solid #ccc',
              borderRadius:4,
              padding:'3px 8px',
              cursor:'pointer',
              fontSize:11,
              color:'#888',
            }}>
            ⚙ API
          </button>
        </div>

        {/* API KEY */}
        {(showSettings||!apiKey)&&(
          <div className="noP" style={{background:'#f8f8f8',border:'1px solid #ddd',borderRadius:6,padding:'12px 16px',margin:'14px 0'}}>
            <div style={{fontSize:14,fontWeight:700,marginBottom:6}}>
              {AI_CFG.label} API Key {apiKey&&<span style={{color:'#080',fontWeight:400}}>✓ saved</span>}
            </div>
            <div style={{display:'flex',gap:8}}>
              <input type="password" value={keyInput} onChange={e=>setKeyInput(e.target.value)}
                placeholder={AI_CFG.placeholder} onKeyDown={e=>e.key==='Enter'&&saveKey()}
                style={{flex:1,padding:'6px 10px',border:'1px solid #bbb',borderRadius:4,fontSize:14,fontFamily:'monospace'}}/>
              <button onClick={saveKey} style={btn(1)}>Save</button>
              {apiKey&&<button onClick={()=>setShowSettings(false)} style={btn(0)}>Close</button>}
            </div>
            <div style={{fontSize:12,color:'#999',marginTop:5}}>
              Free at <a href={AI_CFG.consoleUrl} target="_blank" rel="noreferrer" style={{color:'#0056b3'}}>{AI_CFG.consoleName}</a>
              <span style={{marginLeft:8,color:'#bbb'}}>· Using model: <code style={{background:'#eee',padding:'1px 4px',borderRadius:2,fontSize:11}}>{AI_CFG.model}</code></span>
            </div>
          </div>
        )}

        {error&&<div className="noP" style={{background:'#fff0f0',border:'1px solid #d00',borderRadius:6,padding:'10px 14px',color:'#c00',fontSize:14,margin:'10px 0',whiteSpace:'pre-wrap'}}>
          {error}<span style={{float:'right',cursor:'pointer'}} onClick={()=>setError(null)}>✕</span>
        </div>}

        {/* GLOBAL ISSUE COUNTER — shows total unresolved issues across batch */}
        {(openErrorCount>0 || openWarnCount>0) && (
          <div className="noP" style={{
            background: openErrorCount>0 ? '#fef2f2' : '#fffbeb',
            border: `1px solid ${openErrorCount>0 ? '#f87171' : '#fbbf24'}`,
            borderRadius:6,
            padding:'8px 14px',
            margin:'10px 0',
            fontSize:13,
            display:'flex',
            justifyContent:'space-between',
            alignItems:'center',
          }}>
            <span>
              {openErrorCount>0 ? '🛑' : '⚠'} <strong>{openErrorCount+openWarnCount} issue{openErrorCount+openWarnCount>1?'s':''}</strong> across this batch
              {openErrorCount>0 && <span style={{color:'#dc2626',marginLeft:8}}>({openErrorCount} error{openErrorCount>1?'s':''})</span>}
              {openWarnCount>0 && <span style={{color:'#d97706',marginLeft:8}}>({openWarnCount} warning{openWarnCount>1?'s':''})</span>}
            </span>
            <span style={{fontSize:11,color:'#6b7280'}}>scroll down — each invoice with issues has a yellow/red banner</span>
          </div>
        )}

        {/* PAYMENT SUMMARY */}
        {invoices.length>0&&(<>
          <div style={{textAlign:'center',margin:'20px 0 6px'}}>
            <div style={{fontWeight:700,fontSize:22,letterSpacing:1}}>PAYMENT SUMMARY</div>
            <div style={{fontWeight:700,fontSize:16,marginTop:2}}>SUPPLIER: {config.name}</div>
          </div>

          <table style={{width:'100%',borderCollapse:'collapse',marginTop:14}}>
            <thead><tr>
              <th style={{...T.th,width:36}}>NO.</th>
              <th style={{...T.th,width:86}}>DATE</th>
              <th style={{...T.th,width:120}}>INVOICE NO.</th>
              <th style={{...T.th,width:88}}>AMOUNT</th>
              <th style={{...T.th,width:60}}>CN</th>
              <th style={T.th} colSpan={2}>TRANSPORT SUBSIDY</th>
            </tr></thead>
            <tbody>
              {invoices.map((inv,idx)=>{
                const rc=Math.max(inv.groups.length*4,1);  // 4 rows per group: label + CTN + 0.4% + 0.2%
                const cn=cnValues[inv.id]||0;
                const displayNum=idx+1;
                const rows=[];

                const dateInvalid = inv.issues?.some(i=>i.kind==='date' && !inv._issuesDismissed);
                const invNoInvalid = inv.issues?.some(i=>(i.kind==='invoice_no'||i.kind==='duplicate') && !inv._issuesDismissed);

                if(inv.groups.length===0){
                  const me=manualEntry[inv.id]||{rateId:'',ctn:''};
                  rows.push(<tr key={inv.id+'-empty'}>
                    <td style={T.td}>{displayNum}</td>
                    <td style={T.td}>
                      <EditableText
                        value={inv.raw.invoice_date}
                        onCommit={v=>updateInvoiceField(inv.id,'invoice_date',v)}
                        invalid={dateInvalid}
                        placeholder="DD/MM/YYYY"
                      />
                    </td>
                    <td style={T.td}>
                      <div style={{display:'flex',alignItems:'center',justifyContent:'center',gap:6}}>
                        <EditableText
                          value={inv.raw.invoice_no}
                          onCommit={v=>updateInvoiceField(inv.id,'invoice_no',v)}
                          invalid={invNoInvalid}
                          placeholder="IN..."
                        />
                        {inv.image && (
                          <button className="noP" onClick={()=>setPreviewInvId(inv.id)}
                            title="View source invoice image"
                            style={{background:'#fff',border:'1px solid #d1d5db',borderRadius:3,padding:'1px 5px',cursor:'pointer',fontSize:12,lineHeight:1,fontFamily:F}}>
                            👁
                          </button>
                        )}
                      </div>
                    </td>
                    <td style={{...T.td,fontWeight:700,textAlign:'right'}}>
                      <EditableAmount
                        value={inv.raw.total_amount}
                        onCommit={v=>updateInvoiceAmount(inv.id,v)}
                        format={fmt}
                        align="right"
                      />
                    </td>
                    <td style={{...T.td,padding:4}}>
                      <input type="number" step="0.01" value={cn||''} placeholder="0.00"
                        onChange={e=>setCn(inv.id,e.target.value)} className="noP"
                        style={{width:'100%',border:'1px solid #ccc',borderRadius:3,padding:'3px 4px',fontSize:14,fontFamily:F,textAlign:'right',boxSizing:'border-box'}}/>
                      {cn>0&&<div style={{textAlign:'right',fontSize:13,color:'#c00',marginTop:2}}>-{fmt(cn)}</div>}
                    </td>
                    <td style={{...T.td,padding:8}} colSpan={2}>
                      <div className="noP" style={{display:'flex',gap:6,alignItems:'center',flexWrap:'wrap'}}>
                        <span style={{fontSize:12,color:'#888'}}>AI missed this — pick category:</span>
                        <select value={me.rateId}
                          onChange={e=>setManualEntry(p=>({...p,[inv.id]:{...me,rateId:e.target.value}}))}
                          style={{padding:'4px 6px',fontSize:13,border:'1px solid #aaa',borderRadius:3,fontFamily:F}}>
                          <option value="">— Category —</option>
                          {config.rates.map(r=><option key={r.id} value={r.id}>{r.label}</option>)}
                        </select>
                        <input type="number" placeholder="CTN" value={me.ctn}
                          onChange={e=>setManualEntry(p=>({...p,[inv.id]:{...me,ctn:e.target.value}}))}
                          style={{width:70,padding:'4px 6px',fontSize:13,border:'1px solid #aaa',borderRadius:3,fontFamily:F}}/>
                        <button onClick={()=>assignCategory(inv.id,me.rateId,me.ctn)}
                          disabled={!me.rateId||!me.ctn}
                          style={{padding:'4px 12px',fontSize:13,background:(me.rateId&&me.ctn)?'#111':'#ddd',color:'#fff',border:'none',borderRadius:3,cursor:(me.rateId&&me.ctn)?'pointer':'not-allowed',fontWeight:600}}>
                          Apply
                        </button>
                      </div>
                    </td>
                  </tr>);
                } else {
                inv.groups.forEach((g,gi)=>{
                  // ROW 1 — VOLUME LABEL (rowSpan metadata cells live here, on the first row of the group)
                  rows.push(<tr key={inv.id+'-'+gi+'-lbl'}>
                    {gi===0&&<td style={T.td} rowSpan={rc}>{displayNum}</td>}
                    {gi===0&&<td style={T.td} rowSpan={rc}>
                      <EditableText
                        value={inv.raw.invoice_date}
                        onCommit={v=>updateInvoiceField(inv.id,'invoice_date',v)}
                        invalid={dateInvalid}
                        placeholder="DD/MM/YYYY"
                      />
                    </td>}
                    {gi===0&&<td style={T.td} rowSpan={rc}>
                      <div style={{display:'flex',alignItems:'center',justifyContent:'center',gap:6}}>
                        <EditableText
                          value={inv.raw.invoice_no}
                          onCommit={v=>updateInvoiceField(inv.id,'invoice_no',v)}
                          invalid={invNoInvalid}
                          placeholder="IN..."
                        />
                        {inv.image && (
                          <button className="noP" onClick={()=>setPreviewInvId(inv.id)}
                            title="View source invoice image"
                            style={{background:'#fff',border:'1px solid #d1d5db',borderRadius:3,padding:'1px 5px',cursor:'pointer',fontSize:12,lineHeight:1,fontFamily:F}}>
                            👁
                          </button>
                        )}
                      </div>
                    </td>}
                    {gi===0&&<td style={{...T.td,fontWeight:700,padding:'8px 6px',position:'relative',textAlign:'right'}} rowSpan={rc}>
                      <EditableAmount
                        value={inv.raw.total_amount}
                        onCommit={v=>updateInvoiceAmount(inv.id,v)}
                        format={fmt}
                        align="right"
                      />
                    </td>}
                    {gi===0&&<td style={{...T.td,padding:4}} rowSpan={rc}>
                      <input type="number" step="0.01" value={cn||''} placeholder="0.00"
                        onChange={e=>setCn(inv.id,e.target.value)} className="noP"
                        style={{width:'100%',border:'1px solid #ccc',borderRadius:3,padding:'3px 4px',fontSize:14,fontFamily:F,textAlign:'right',boxSizing:'border-box'}}/>
                      {cn>0&&<div style={{textAlign:'right',fontSize:13,color:'#c00',marginTop:2}}>-{fmt(cn)}</div>}
                    </td>}
                    <td colSpan={2} style={{
                      border:B,
                      padding:'6px 12px',
                      fontSize:16,
                      fontWeight:600,
                      color:'#333',
                      background:'#f9fafb',
                      textAlign:'left',
                      fontFamily:F,
                    }}>{g.label}</td>
                  </tr>);

                  // ROW 2 — CTN x RM = subtotal
                  rows.push(<tr key={inv.id+'-'+gi+'-c'}>
                    <td style={{...T.subL,padding:'4px 8px'}}>
                      <span style={{display:'inline-flex',alignItems:'baseline',gap:4,justifyContent:'flex-end',width:'100%',whiteSpace:'nowrap'}}>
                        <EditableCtn
                          value={g.ctn}
                          onCommit={v=>updateGroupCtn(inv.id,g.id,v)}
                        />
                        <span>CTN x RM{g.rate.toFixed(2)} =</span>
                      </span>
                    </td>
                    <td style={T.subR}>{fmt(g.ctn*g.rate)}</td>
                  </tr>);

                  // ROW 3 — + 0.4% (editable)
                  rows.push(<tr key={inv.id+'-'+gi+'-p1'}>
                    <td style={T.subL}>+ 0.4% =</td>
                    <td style={T.subR}>
                      <EditableAmount
                        value={inv.subsidy.p1}
                        onCommit={v=>updateSubsidyLine(inv.id,'p1',v)}
                        format={fmt}
                      />
                    </td>
                  </tr>);

                  // ROW 4 — + 0.2% (editable)
                  rows.push(<tr key={inv.id+'-'+gi+'-p2'}>
                    <td style={T.subL}>+ 0.2% =</td>
                    <td style={T.subR}>
                      <EditableAmount
                        value={inv.subsidy.p2}
                        onCommit={v=>updateSubsidyLine(inv.id,'p2',v)}
                        format={fmt}
                      />
                    </td>
                  </tr>);
                });
                }

                // PATCH 8 — issues banner row (replaces the old single-line warning)
                if(inv.issues && inv.issues.length > 0 && !inv._issuesDismissed){
                  const hasError = inv.issues.some(i=>i.severity==='error');
                  rows.push(<tr key={inv.id+'-issues'} className="noP">
                    <td colSpan={7} style={{padding:'10px 12px', background:'#fff'}}>
                      <div style={{
                        background: hasError ? '#fef2f2' : '#fffbeb',
                        border: `1px solid ${hasError ? '#f87171' : '#fbbf24'}`,
                        borderRadius:6,
                        padding:'10px 14px',
                        fontSize:13,
                      }}>
                        <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:6,gap:8}}>
                          <strong style={{fontSize:14}}>
                            {hasError ? '🛑' : '⚠'} {inv.issues.length} issue{inv.issues.length>1?'s':''} on invoice {inv.raw.invoice_no||'(no number)'} — verify before exporting
                          </strong>
                          <div style={{display:'flex',gap:6}}>
                            {inv.image && (
                              <button onClick={()=>setPreviewInvId(inv.id)}
                                style={{padding:'3px 10px',fontSize:11,border:'1px solid #d1d5db',background:'#fff',borderRadius:4,cursor:'pointer',fontFamily:F}}>
                                👁 View source
                              </button>
                            )}
                            {hasError && (
                              <button onClick={()=>removeInvoice(inv.id)}
                                style={{padding:'3px 10px',fontSize:11,border:'1px solid #dc2626',background:'#fff',color:'#dc2626',borderRadius:4,cursor:'pointer',fontFamily:F}}>
                                Remove
                              </button>
                            )}
                            <button onClick={()=>dismissIssues(inv.id)}
                              style={{padding:'3px 10px',fontSize:11,border:'1px solid #d1d5db',background:'#fff',borderRadius:4,cursor:'pointer',fontFamily:F}}>
                              Dismiss
                            </button>
                          </div>
                        </div>
                        <ul style={{margin:0,paddingLeft:18,lineHeight:1.5}}>
                          {inv.issues.map((iss,i)=>(
                            <li key={i} style={{marginBottom: iss.details ? 6 : 2}}>
                              <span style={{
                                display:'inline-block',padding:'1px 6px',marginRight:6,fontSize:10,fontWeight:700,
                                borderRadius:3,background: iss.severity==='error' ? '#dc2626' : '#d97706',
                                color:'#fff',textTransform:'uppercase',verticalAlign:'middle',letterSpacing:0.3,
                              }}>{iss.kind.replace(/_/g,' ')}</span>
                              {iss.msg}
                              {iss.details && iss.details.length > 0 && (
                                <ul style={{paddingLeft:14,marginTop:3,color:'#6b7280',fontSize:12}}>
                                  {iss.details.slice(0,5).map((d,j)=><li key={j}>{d}</li>)}
                                  {iss.details.length > 5 && <li>…and {iss.details.length - 5} more</li>}
                                </ul>
                              )}
                            </li>
                          ))}
                        </ul>
                      </div>
                    </td>
                  </tr>);
                }

                return <React.Fragment key={inv.id}>{rows}</React.Fragment>;
              })}
              {/* COLUMN FOOTER — invoice-total under AMOUNT column, credit-note under CN column */}
              <tr>
                <td colSpan={3} style={{border:'none'}}/>
                <td style={{...T.td,borderTop:'2px solid #000',fontWeight:700,background:'#ffe600',fontSize:18,textAlign:'right',fontVariantNumeric:'tabular-nums'}}>{fmt(gT)}</td>
                <td style={{...T.td,borderTop:'2px solid #000',fontWeight:700,textAlign:'right',fontVariantNumeric:'tabular-nums',color:totalCn?'#c00':'#000'}}>{totalCn?'-'+fmt(totalCn):'RM0.00'}</td>
                <td colSpan={2} style={{border:'none'}}/>
              </tr>
              {/* SUMMARY BOX — right-aligned subsidy breakdown */}
              <tr><td colSpan={7} style={{padding:6,border:'none'}}/></tr>
              <tr>
                <td colSpan={5} style={{border:'none'}}/>
                <td style={T.bxL}>CARTON:</td>
                <td style={T.bxR}>{fmt(gC)}</td>
              </tr>
              <tr>
                <td colSpan={5} style={{border:'none'}}/>
                <td style={T.bxL}>0.4%:</td>
                <td style={T.bxR}>{fmt(gP1)}</td>
              </tr>
              <tr>
                <td colSpan={5} style={{border:'none'}}/>
                <td style={T.bxL}>0.2%:</td>
                <td style={T.bxR}>{fmt(gP2)}</td>
              </tr>
              <tr>
                <td colSpan={5} style={{border:'none'}}/>
                <td style={{...T.bxL,borderTop:'1px solid #aaa',fontWeight:700}}>TOTAL SUBSIDY:</td>
                <td style={{...T.bxR,borderTop:'1px solid #aaa',fontWeight:700}}>{fmt(gS)}</td>
              </tr>
            </tbody>
          </table>

          {/* TOTAL AMOUNT PAYABLE */}
          <div className="total-payable" style={{marginTop:16,textAlign:'right'}}>
            <div style={{fontSize:22,fontWeight:700,letterSpacing:0.5}}>
              TOTAL AMOUNT PAYABLE = {fmt(tP)}
            </div>
          </div>

          {/* BUTTONS */}
          <div className="noP" style={{display:'flex',gap:8,justifyContent:'center',marginTop:28}}>
            <button style={btn(0)} onClick={()=>setUploading(true)}>+ Add Invoice</button>
            <button style={btn(1)} onClick={()=>window.print()}>🖨 Print / Save PDF</button>
            <button style={btn(0)} onClick={downloadExcel}>↓ Excel</button>
            <button style={{...btn(0),color:'#aaa',borderColor:'#ddd'}} onClick={reset}>Reset</button>
          </div>
        </>)}

        {/* UPLOAD */}
        {showUpload&&!processing&&apiKey&&(
          <div ref={uploadAreaRef} className="noP"
            style={{
              border:'2px dashed '+(drag?'#c87b00':invoices.length>0?'#c87b00':'#ccc'),
              borderRadius:8,padding:'48px 20px',textAlign:'center',
              cursor:'pointer',
              background:drag?'#fffbeb':invoices.length>0?'#fffbeb':'#fafafa',
              marginTop:18,
              boxShadow: invoices.length>0 ? '0 0 0 4px rgba(200,123,0,0.12)' : 'none',
              transition:'background .2s, border-color .2s',
            }}
            onDragOver={e=>{e.preventDefault();setDrag(true);}}
            onDragLeave={()=>setDrag(false)}
            onDrop={e=>{e.preventDefault();setDrag(false);if(e.dataTransfer?.files?.length)processFiles(e.dataTransfer.files);}}
            onClick={()=>fileRef.current?.click()}>
            <div style={{fontSize:32,marginBottom:8,opacity:.5}}>📄</div>
            <div style={{fontSize:16,fontWeight:600}}>
              {invoices.length>0?`Add more invoices to your batch of ${invoices.length}`:'Drop invoice photos or PDFs here'}</div>
            <div style={{fontSize:13,color:'#999',marginTop:3}}>or click to browse — JPG, PNG, PDF (multi-page OK)</div>
            <input ref={fileRef} type="file" accept="image/*,.pdf,application/pdf" multiple style={{display:'none'}}
              onChange={e=>{if(e.target.files?.length)processFiles(e.target.files);e.target.value='';}}/>
            {invoices.length>0&&<button style={{...btn(0),marginTop:12}} onClick={e=>{e.stopPropagation();setUploading(false);}}>Cancel</button>}
          </div>
        )}

        {processing&&(
          <div className="noP" style={{textAlign:'center',padding:'60px 20px'}}>
            <div style={{width:32,height:32,border:'3px solid #eee',borderTop:'3px solid #000',borderRadius:'50%',margin:'0 auto 12px',animation:'spin .7s linear infinite'}}/>
            <div style={{fontSize:14,color:'#888'}}>
              Extracting with {AI_CFG.label}...{processingCount.total>1&&` (${processingCount.done}/${processingCount.total})`}
            </div>
          </div>
        )}
      </div>

      {/* SIDE-BY-SIDE COMPARISON VIEW — source image (left) + extracted data summary (right) */}
      {previewInv && (
        <div className="noP"
          onClick={()=>setPreviewInvId(null)}
          style={{
            position:'fixed',
            inset:0,
            background:'rgba(0,0,0,0.85)',
            display:'flex',
            alignItems:'center',
            justifyContent:'center',
            zIndex:9999,
            padding:20,
          }}>
          <div
            onClick={e=>e.stopPropagation()}
            style={{
              background:'#fff',
              width:'min(1400px, 96vw)',
              height:'min(900px, 92vh)',
              display:'flex',
              borderRadius:8,
              overflow:'hidden',
              boxShadow:'0 8px 48px rgba(0,0,0,0.4)',
              fontFamily:F,
            }}>

            {/* LEFT — Source invoice photo */}
            <div style={{
              flex:'1 1 60%',
              background:'#111',
              display:'flex',
              alignItems:'center',
              justifyContent:'center',
              padding:16,
              overflow:'auto',
            }}>
              {previewInv.image ? (
                <img src={previewInv.image} alt="Source invoice"
                  style={{maxWidth:'100%',maxHeight:'100%',objectFit:'contain',background:'#fff'}}/>
              ) : (
                <div style={{color:'#888',fontSize:14}}>No source image available</div>
              )}
            </div>

            {/* RIGHT — Extracted data summary */}
            <div style={{
              flex:'1 1 40%',
              minWidth:380,
              padding:'18px 22px',
              overflowY:'auto',
              background:'#fafafa',
              borderLeft:'1px solid #e5e7eb',
              fontSize:13,
              color:'#111',
            }}>
              <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:14,paddingBottom:10,borderBottom:'1px solid #e5e7eb'}}>
                <div>
                  <div style={{fontSize:11,color:'#6b7280',textTransform:'uppercase',letterSpacing:0.5,fontWeight:600}}>Verify against source</div>
                  <div style={{fontSize:16,fontWeight:700,marginTop:2}}>Extracted Data</div>
                </div>
                <button onClick={()=>setPreviewInvId(null)}
                  style={{padding:'5px 12px',fontSize:12,border:'1px solid #d1d5db',background:'#fff',borderRadius:4,cursor:'pointer',fontFamily:F}}>
                  Close (Esc)
                </button>
              </div>

              {/* Key fields — editable */}
              <div style={{display:'grid',gridTemplateColumns:'130px 1fr',rowGap:11,columnGap:14,marginBottom:18,alignItems:'center'}}>
                <div style={{color:'#6b7280'}}>Invoice No</div>
                <ModalInput
                  value={previewInv.raw.invoice_no}
                  onCommit={v=>updateInvoiceField(previewInv.id,'invoice_no',v)}
                  placeholder="IN..."
                  mono
                />

                <div style={{color:'#6b7280'}}>Date</div>
                <ModalInput
                  value={previewInv.raw.invoice_date}
                  onCommit={v=>updateInvoiceField(previewInv.id,'invoice_date',v)}
                  placeholder="DD/MM/YYYY"
                />

                <div style={{color:'#6b7280'}}>Supplier</div>
                <ModalInput
                  value={previewInv.raw.supplier}
                  onCommit={v=>updateInvoiceField(previewInv.id,'supplier',v)}
                  placeholder="Supplier name"
                />

                <div style={{color:'#6b7280'}}>Total Amount</div>
                <div style={{display:'flex',alignItems:'center',gap:8}}>
                  <span style={{fontWeight:700,fontSize:16}}>RM</span>
                  <ModalInput
                    value={previewInv.raw.total_amount}
                    onCommit={v=>updateInvoiceAmount(previewInv.id,v)}
                    type="number"
                    step="0.01"
                    bold
                  />
                </div>

                <div style={{color:'#6b7280'}}>PRODUCT TOTAL</div>
                <div style={{display:'flex',alignItems:'center',gap:8}}>
                  <ModalInput
                    value={previewInv.declaredTotal}
                    onCommit={v=>updateDeclaredTotal(previewInv.id,v)}
                    type="number"
                    narrow
                  />
                  <span style={{color:'#6b7280',fontSize:12}}>CTN (from invoice header)</span>
                </div>
              </div>

              {/* Line items */}
              <div style={{fontSize:11,fontWeight:700,color:'#6b7280',textTransform:'uppercase',letterSpacing:0.5,marginBottom:6}}>
                Line items extracted ({previewInv.items?.length || 0})
              </div>
              <div style={{background:'#fff',border:'1px solid #e5e7eb',borderRadius:4,padding:'6px 10px',marginBottom:16,maxHeight:180,overflowY:'auto'}}>
                {previewInv.items?.length > 0 ? previewInv.items.map((it,i)=>(
                  <div key={i} style={{padding:'5px 0',borderBottom:i<previewInv.items.length-1?'1px solid #f3f4f6':'none'}}>
                    <div style={{fontFamily:'monospace',fontSize:11,fontWeight:600}}>{it.description || it.product_code || '?'}</div>
                    <div style={{color:'#6b7280',fontSize:11,marginTop:2}}>
                      qty {it.qty}
                      {it.is_foc && <span style={{marginLeft:6,padding:'1px 5px',background:'#f3f4f6',borderRadius:3,fontSize:10,fontWeight:600}}>FOC</span>}
                      <span style={{marginLeft:8}}>• {fmt(it.amount)}</span>
                      {it.category
                        ? <span style={{marginLeft:8,color:'#059669'}}>→ {it.category.label}</span>
                        : <span style={{marginLeft:8,color:'#dc2626'}}>⚠ no category</span>}
                    </div>
                  </div>
                )) : <div style={{padding:'8px 0',color:'#6b7280',fontStyle:'italic'}}>No items extracted</div>}
              </div>

              {/* Categories — CTN editable, with inline manual-add UI */}
              <div style={{fontSize:11,fontWeight:700,color:'#6b7280',textTransform:'uppercase',letterSpacing:0.5,marginBottom:6}}>
                Subsidy categories
              </div>
              <div style={{background:'#fff',border:'1px solid #e5e7eb',borderRadius:4,padding:'10px 12px',marginBottom:16}}>
                {previewInv.groups?.length > 0 ? previewInv.groups.map((g,i)=>(
                  <div key={i} style={{display:'flex',justifyContent:'space-between',padding:'4px 0',alignItems:'center',fontSize:12,gap:6}}>
                    <span style={{color:'#6b7280',flex:1}}>{g.label}</span>
                    <ModalInput
                      value={g.ctn}
                      onCommit={v=>updateGroupCtn(previewInv.id,g.id,v)}
                      type="number"
                      narrow
                    />
                    <span style={{color:'#6b7280'}}>× RM{g.rate.toFixed(2)} =</span>
                    <span style={{fontWeight:600,minWidth:70,textAlign:'right'}}>{fmt(g.ctn*g.rate)}</span>
                    <button
                      onClick={()=>removeGroup(previewInv.id, g.id)}
                      title={`Remove ${g.label}`}
                      style={{
                        background:'none',
                        border:'none',
                        color:'#9ca3af',
                        cursor:'pointer',
                        fontSize:18,
                        lineHeight:1,
                        padding:'0 6px',
                        marginLeft:2,
                        borderRadius:3,
                        fontFamily:F,
                      }}
                      onMouseEnter={e=>{e.currentTarget.style.color='#dc2626';}}
                      onMouseLeave={e=>{e.currentTarget.style.color='#9ca3af';}}>
                      ×
                    </button>
                  </div>
                )) : <div style={{color:'#6b7280',fontStyle:'italic',fontSize:12,marginBottom:8}}>
                  No categories auto-matched. Pick one manually below.
                </div>}

                {/* Manual category entry — always available so user can add/correct */}
                <div style={{
                  display:'flex',
                  gap:6,
                  alignItems:'center',
                  marginTop: previewInv.groups?.length > 0 ? 10 : 0,
                  paddingTop: previewInv.groups?.length > 0 ? 10 : 0,
                  borderTop: previewInv.groups?.length > 0 ? '1px dashed #e5e7eb' : 'none',
                  flexWrap:'wrap',
                }}>
                  <select
                    value={(manualEntry[previewInv.id]||{}).rateId||''}
                    onChange={e=>setManualEntry(p=>({...p,[previewInv.id]:{...(p[previewInv.id]||{}),rateId:e.target.value}}))}
                    style={{padding:'5px 8px',fontSize:12,border:'1px solid #d1d5db',borderRadius:4,fontFamily:F,flex:1,minWidth:140,background:'#fff'}}>
                    <option value="">— Pick category —</option>
                    {config.rates.map(r=><option key={r.id} value={r.id}>{r.label}</option>)}
                  </select>
                  <input
                    type="number"
                    placeholder="CTN"
                    value={(manualEntry[previewInv.id]||{}).ctn||''}
                    onChange={e=>setManualEntry(p=>({...p,[previewInv.id]:{...(p[previewInv.id]||{}),ctn:e.target.value}}))}
                    style={{width:64,padding:'5px 8px',fontSize:12,border:'1px solid #d1d5db',borderRadius:4,fontFamily:F,textAlign:'right'}}/>
                  <button
                    onClick={()=>{
                      const me = manualEntry[previewInv.id]||{};
                      assignCategory(previewInv.id, me.rateId, me.ctn);
                    }}
                    disabled={!(manualEntry[previewInv.id]||{}).rateId || !(manualEntry[previewInv.id]||{}).ctn}
                    style={{
                      padding:'5px 14px',
                      fontSize:12,
                      background: ((manualEntry[previewInv.id]||{}).rateId && (manualEntry[previewInv.id]||{}).ctn) ? '#111' : '#ddd',
                      color:'#fff',
                      border:'none',
                      borderRadius:4,
                      cursor: ((manualEntry[previewInv.id]||{}).rateId && (manualEntry[previewInv.id]||{}).ctn) ? 'pointer' : 'not-allowed',
                      fontWeight:600,
                      fontFamily:F,
                    }}>
                    {previewInv.groups?.length > 0 ? '+ Add' : 'Apply'}
                  </button>
                </div>
              </div>

              {/* Subsidy breakdown — all 3 lines editable */}
              <div style={{fontSize:11,fontWeight:700,color:'#6b7280',textTransform:'uppercase',letterSpacing:0.5,marginBottom:6}}>
                Transport subsidy <span style={{textTransform:'none',fontWeight:400,fontSize:10,color:'#9ca3af',marginLeft:4}}>(click any value to adjust)</span>
              </div>
              <div style={{background:'#fff',border:'1px solid #e5e7eb',borderRadius:4,padding:'10px 12px',marginBottom:16,fontSize:13}}>
                <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',padding:'3px 0',gap:8}}>
                  <span style={{color:'#6b7280'}}>Carton</span>
                  <div style={{width:110}}>
                    <ModalInput
                      value={previewInv.subsidy.carton ?? 0}
                      onCommit={v=>updateSubsidyLine(previewInv.id,'carton',v)}
                      type="number" step="0.01" narrow
                    />
                  </div>
                </div>
                <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',padding:'3px 0',gap:8}}>
                  <span style={{color:'#6b7280'}}>+ 0.4%</span>
                  <div style={{width:110}}>
                    <ModalInput
                      value={previewInv.subsidy.p1 ?? 0}
                      onCommit={v=>updateSubsidyLine(previewInv.id,'p1',v)}
                      type="number" step="0.01" narrow
                    />
                  </div>
                </div>
                <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',padding:'3px 0',gap:8}}>
                  <span style={{color:'#6b7280'}}>+ 0.2%</span>
                  <div style={{width:110}}>
                    <ModalInput
                      value={previewInv.subsidy.p2 ?? 0}
                      onCommit={v=>updateSubsidyLine(previewInv.id,'p2',v)}
                      type="number" step="0.01" narrow
                    />
                  </div>
                </div>
                <div style={{display:'flex',justifyContent:'space-between',padding:'8px 0 2px',borderTop:'1px solid #e5e7eb',marginTop:4,fontWeight:700}}>
                  <span>Total subsidy</span><span>{fmt(previewInv.subsidy.total)}</span>
                </div>
              </div>

              {/* Issues if any */}
              {previewInv.issues?.length > 0 && (
                <div style={{
                  background: previewInv.issues.some(i=>i.severity==='error') ? '#fef2f2' : '#fffbeb',
                  border: `1px solid ${previewInv.issues.some(i=>i.severity==='error') ? '#f87171' : '#fbbf24'}`,
                  borderRadius:4,
                  padding:'10px 12px',
                  marginBottom:14,
                  fontSize:12,
                }}>
                  <div style={{fontWeight:700,marginBottom:6}}>
                    {previewInv.issues.some(i=>i.severity==='error') ? '🛑' : '⚠'} {previewInv.issues.length} unresolved issue{previewInv.issues.length>1?'s':''}
                  </div>
                  <ul style={{margin:0,paddingLeft:16,lineHeight:1.5}}>
                    {previewInv.issues.map((iss,i)=>(
                      <li key={i}>{iss.msg}</li>
                    ))}
                  </ul>
                </div>
              )}

              <div style={{padding:'10px 12px',background:'#f0f9ff',border:'1px solid #93c5fd',borderRadius:4,fontSize:11,color:'#1e40af',lineHeight:1.5}}>
                💡 Compare numbers on the right against the photo on the left. If anything's off, close this view and click the field in the table to edit.
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const T={
  th:{border:B,padding:'10px 8px',fontWeight:700,fontSize:16,textAlign:'center',background:'#f0f0f0',fontFamily:F},
  td:{border:B,padding:'8px 10px',fontSize:16,textAlign:'center',verticalAlign:'middle',fontFamily:F},
  cat:{border:B,padding:'6px 8px',fontSize:16,fontWeight:700,textDecoration:'underline',textAlign:'center',fontFamily:F},
  subL:{border:B,padding:'6px 12px',fontSize:16,textAlign:'right',fontFamily:F,fontVariantNumeric:'tabular-nums'},
  subR:{border:B,padding:'6px 12px',fontSize:16,textAlign:'center',fontWeight:700,fontFamily:F,whiteSpace:'nowrap',fontVariantNumeric:'tabular-nums',width:110},
  bxL:{border:B,padding:'6px 14px',fontSize:16,fontWeight:700,textAlign:'right',background:'#f0f0f0',fontFamily:F},
  bxR:{border:B,padding:'6px 14px',fontSize:16,fontWeight:700,textAlign:'right',fontFamily:F,minWidth:110,width:110,whiteSpace:'nowrap',fontVariantNumeric:'tabular-nums'},
};
const btn=p=>({padding:'8px 18px',borderRadius:5,border:p?'none':'1px solid #aaa',fontWeight:600,fontSize:14,cursor:'pointer',background:p?'#111':'#fff',color:p?'#fff':'#333',fontFamily:F});
